export function animeEpisode(item){
 const rows=mappings[item.type==='tv'?`tv:${item.id}:${item.season}`:`movie:${item.id}`];
 if(!rows)return null;
 const episode=item.type==='tv'?item.episode:1;
 const eligible=rows.filter(([offset])=>offset<episode);
 if(!eligible.length)return null;
 const offset=Math.max(...eligible.map(row=>row[0]));
 const candidates=eligible.filter(row=>row[0]===offset);
 // Conflicting mappings are excluded instead of guessing a title.
 if(candidates.length!==1)return null;
 return {id:candidates[0][1],episode:episode-offset};
}
